 10→import { toast } from "sonner";
 11→import { Copy, Mail, Check, ChevronDown, Info, RefreshCw, Loader2 } from "lucide-react";
 12→
 13→const EmailInboxCard = () => {
 14→  const { user, profile, refreshProfile } = useAuth();
 15→  const [togglingEmail, setTogglingEmail] = useState(false);
 16→  const [copied, setCopied] = useState(false);
 17→  const [howItWorksOpen, setHowItWorksOpen] = useState(false);
 18→  const [regenerating, setRegenerating] = useState(false);
 19→
 20→  const handleCopyInbox = () => {
 21→    if (profile?.inbox_email) {
 22→      navigator.clipboard.writeText(profile.inbox_email);
 23→      setCopied(true);
 24→      toast.success("Inbox email copied to clipboard.");
 25→      setTimeout(() => setCopied(false), 2000);
 26→    }
 27→  };
 28→
 29→  const handleRegenerateInbox = async () => {
 30→    if (!user) return;
 31→    setRegenerating(true);
 32→    try {
 33→      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user.id });
 34→      if (error) throw error;
 35→      await refreshProfile();
 36→      toast.success(`Inbox regenerated: ${data}`);
 37→    } catch (e: any) {
 38→      toast.error(e.message || "Failed to regenerate inbox");
 39→    } finally {
 40→      setRegenerating(false);
 41→    }
 42→  };
 43→
 44→  const handleToggleEmail = async (checked: boolean) => {
 45→    if (!user) return;
 46→    setTogglingEmail(true);
 47→    const { error } = await supabase
 48→      .from("profiles")
 49→      .update({ email_enabled: checked })
 50→      .eq("user_id", user.id);
 51→    if (error) {
 52→      toast.error(error.message);
 53→    } else {
 54→      await refreshProfile();
 55→      toast.success(checked ? "Email enabled" : "Email disabled");
 56→    }
 57→    setTogglingEmail(false);
 58→  };
 59→
 60→  return (
 61→    <Card className="overflow-hidden">
 62→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 63→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 64→          <Mail className="h-4.5 w-4.5 text-primary" />
 65→        </div>
 66→        <div>
 67→          <h3 className="text-base font-semibold text-foreground">Email Inbox</h3>
 68→          <p className="text-xs text-muted-foreground">
 69→            Forward resumes here to auto-add them to your jobs.
 70→          </p>
 71→        </div>
 72→      </div>
 73→      <CardContent className="px-6 pt-3 pb-5 space-y-4">
 74→        {profile?.inbox_email ? (
 75→          <>
 76→            <div>
 77→              <Label className="text-xs text-muted-foreground mb-1.5 block">Your fallback inbox</Label>
 78→              <div className="flex items-center gap-2">
 79→                <Input
 80→                  value={profile.inbox_email}
 81→                  readOnly
 82→                  className="font-mono text-sm bg-accent/50"
 83→                />
 84→                <Button
 85→                  variant="outline"
 86→                  size="icon"
 87→                  onClick={handleCopyInbox}
 88→                  title="Copy"
 89→                  aria-label="Copy inbox email"
 90→                  className="shrink-0"
 91→                >
 92→                  {copied ? (
 93→                    <Check className="h-4 w-4 text-primary" />
 94→                  ) : (
 95→                    <Copy className="h-4 w-4" />
 96→                  )}
 97→                </Button>
 98→                <Button
 99→                  variant="outline"
100→                  size="icon"
101→                  onClick={handleRegenerateInbox}
102→                  title="Regenerate inbox email"
103→                  aria-label="Regenerate inbox email"
104→                  className="shrink-0"
105→                  disabled={regenerating}
106→                >
107→                  {regenerating ? (
108→                    <Loader2 className="h-4 w-4 animate-spin" />
109→                  ) : (
110→                    <RefreshCw className="h-4 w-4" />
111→                  )}
112→                </Button>
113→              </div>
114→            </div>
115→            <p className="text-xs text-muted-foreground">
116→              Each job also gets its own unique inbox email. Check the job detail page to copy it.
117→            </p>
118→          </>
119→        ) : (
120→          <div className="rounded-md bg-accent/50 px-3 py-3 text-sm text-muted-foreground text-center">
121→            No inbox email assigned yet.
122→          </div>
123→        )}
124→        <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
125→          <Label htmlFor="email-toggle" className="text-sm font-medium cursor-pointer">
126→            Email ingestion enabled
127→          </Label>
128→          <Switch
129→            id="email-toggle"
130→            checked={profile?.email_enabled ?? true}
131→            onCheckedChange={handleToggleEmail}
132→            disabled={togglingEmail}
133→          />
134→        </div>
135→
136→        {/* How it works */}
137→        <Collapsible open={howItWorksOpen} onOpenChange={setHowItWorksOpen}>
138→          <CollapsibleTrigger asChild>
139→            <Button variant="ghost" size="sm" className="w-full justify-between text-muted-foreground text-xs">
140→              <span className="flex items-center gap-1.5">
141→                <Info className="h-3.5 w-3.5" />
142→                How email ingestion works
143→              </span>
144→              <ChevronDown className={`h-3.5 w-3.5 transition-transform ${howItWorksOpen ? "rotate-180" : ""}`} />
145→            </Button>
146→          </CollapsibleTrigger>
147→          <CollapsibleContent className="pt-2">
148→            <div className="rounded-md bg-muted/50 p-3 text-xs text-muted-foreground space-y-2.5">
149→              <p><strong>Per-job inbox:</strong> Each job gets a unique email address (e.g. <code className="bg-muted px-1 py-0.5 rounded text-[11px]">you+j-abc123@inbound.rankora.co</code>). Forward resumes to it and they'll be attached directly to that job.</p>
150→              <p><strong>Fallback inbox:</strong> Your personal inbox above routes resumes to your most recent pending job. Use this when you don't need job-specific routing.</p>
151→              <p><strong>Routing priority:</strong> Job-specific inbox is checked first. If no match, the fallback inbox routes to your latest pending job. If no pending job exists, one is auto-created.</p>
152→              <p><strong>Supported formats:</strong> PDF and DOCX attachments only. Max 20 attachments per email.</p>
153→            </div>
154→          </CollapsibleContent>
155→        </Collapsible>
156→      </CardContent>
157→    </Card>
158→  );
159→};
160→
161→export default EmailInboxCard;
