 13→const EmailIngestLogsCard = () => {
 14→  const [search, setSearch] = useState("");
 15→  const [statusFilter, setStatusFilter] = useState<string>("all");
 16→
 17→  const { data: logs = [], dataUpdatedAt, refetch, isFetching } = useQuery({
 18→    queryKey: ["email_ingest_logs", statusFilter],
 19→    queryFn: async () => {
 20→      let query = supabase
 21→        .from("email_ingest_logs")
 22→        .select("*")
 23→        .order("created_at", { ascending: false })
 24→        .limit(100);
 25→
 26→      if (statusFilter !== "all") {
 27→        query = query.eq("status", statusFilter);
 28→      }
 29→
 30→      const { data, error } = await query;
 31→      if (error) throw error;
 32→      return data as Array<{
 33→        id: string;
 34→        created_at: string;
 35→        sender: string | null;
 36→        recipient: string | null;
 37→        user_id: string | null;
 38→        job_id: string | null;
 39→        status: string;
 40→        error_message: string | null;
 41→        attachments_count: number;
 42→        resumes_created: number;
 43→      }>;
 44→    },
 45→    refetchInterval: 30000,
 46→  });
 47→
 48→  const filtered = logs.filter(
 49→    (l) =>
 50→      !search ||
 51→      l.sender?.toLowerCase().includes(search.toLowerCase()) ||
 52→      l.recipient?.toLowerCase().includes(search.toLowerCase()) ||
 53→      l.error_message?.toLowerCase().includes(search.toLowerCase())
 54→  );
 55→
 56→  const getStatusBadge = (status: string) => {
 57→    switch (status) {
 58→      case "success":
 59→        return <Badge variant="default" className="text-xs">Success</Badge>;
 60→      case "rejected":
 61→        return <Badge variant="secondary" className="text-xs">Rejected</Badge>;
 62→      case "error":
 63→        return <Badge variant="destructive" className="text-xs">Error</Badge>;
 64→      default:
 65→        return <Badge variant="outline" className="text-xs">{status}</Badge>;
 66→    }
 67→  };
 68→
 69→  return (
 70→    <Card>
 71→      <CardHeader className="pb-3">
 72→        <CardTitle className="text-lg flex items-center gap-2">
 73→          <Activity className="h-5 w-5" /> Ingestion Logs
 74→        </CardTitle>
 75→        <div className="flex items-center justify-between">
 76→          <CardDescription>Recent inbound email activity and errors.</CardDescription>
 77→          <div className="flex items-center gap-2">
 78→            {dataUpdatedAt > 0 && (
 79→              <span className="text-[11px] text-muted-foreground">
 80→                Updated {new Date(dataUpdatedAt).toLocaleTimeString()}
 81→              </span>
 82→            )}
 83→            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => refetch()} disabled={isFetching} title="Refresh logs">
 84→              <RefreshCw className={`h-3.5 w-3.5 ${isFetching ? "animate-spin" : ""}`} />
 85→            </Button>
 86→          </div>
 87→        </div>
 88→      </CardHeader>
 89→      <CardContent className="space-y-4">
 90→        <div className="flex items-center gap-3">
 91→          <div className="relative flex-1 max-w-sm">
 92→            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
 93→            <Input
 94→              placeholder="Search by sender or error..."
 95→              value={search}
 96→              onChange={(e) => setSearch(e.target.value)}
 97→              className="pl-9"
 98→            />
 99→          </div>
100→          <Select value={statusFilter} onValueChange={setStatusFilter}>
101→            <SelectTrigger className="w-[130px]">
102→              <SelectValue placeholder="Status" />
103→            </SelectTrigger>
104→            <SelectContent>
105→              <SelectItem value="all">All</SelectItem>
106→              <SelectItem value="success">Success</SelectItem>
107→              <SelectItem value="rejected">Rejected</SelectItem>
108→              <SelectItem value="error">Error</SelectItem>
109→            </SelectContent>
110→          </Select>
111→        </div>
112→
113→        <div className="rounded-md border">
114→          <Table>
115→            <TableHeader>
116→              <TableRow>
117→                <TableHead>Time</TableHead>
118→                <TableHead>Sender</TableHead>
119→                <TableHead>Recipient</TableHead>
120→                <TableHead>Status</TableHead>
121→                <TableHead className="text-right">Files</TableHead>
122→                <TableHead>Error</TableHead>
123→              </TableRow>
124→            </TableHeader>
125→            <TableBody>
126→              {filtered.length === 0 ? (
127→                <TableRow>
128→                  <TableCell colSpan={6} className="text-center text-muted-foreground py-8">
129→                    No logs yet
130→                  </TableCell>
131→                </TableRow>
132→              ) : (
133→                filtered.map((log) => (
134→                  <TableRow key={log.id}>
135→                    <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
136→                      {format(new Date(log.created_at), "MMM d, HH:mm")}
137→                    </TableCell>
138→                    <TableCell className="text-sm max-w-[180px] truncate">{log.sender || "—"}</TableCell>
139→                    <TableCell>
140→                      <code className="text-xs bg-muted px-1 py-0.5 rounded truncate max-w-[200px] block">
141→                        {log.recipient || "—"}
142→                      </code>
143→                    </TableCell>
144→                    <TableCell>{getStatusBadge(log.status)}</TableCell>
145→                    <TableCell className="text-right text-sm">
146→                      {log.resumes_created}/{log.attachments_count}
147→                    </TableCell>
148→                    <TableCell className="text-xs text-destructive max-w-[200px] truncate">
149→                      {log.error_message || "—"}
150→                    </TableCell>
151→                  </TableRow>
152→                ))
153→              )}
154→            </TableBody>
155→          </Table>
156→        </div>
157→      </CardContent>
158→    </Card>
159→  );
160→};
161→
162→export default EmailIngestLogsCard;
